render_chart <- function(data, cfg, manifest) { chart_open_device(cfg$outputPath, cfg$format); plot.new(); par(mar = c(0, 0, 2, 0)); title(main = cfg$title %||% "数据表"); txt <- capture.output(print(utils::head(data, 20), row.names = FALSE)); text(0, seq(0.95, 0.05, length.out = length(txt)), labels = txt, adj = c(0, 0.5), family = "mono", cex = 0.85); grDevices::dev.off(); cfg$outputPath }
